/*
 * The service worker — what lets the app open with no connection.
 *
 * Hand-written rather than generated by a plugin. The build is a static
 * export, so "the app shell" is just the files in `out/`, and
 * `scripts/build-sw.mjs` lists them into the line below after every build.
 * That is the whole of what a precaching library would have done here.
 *
 * It is registered only by a production web build (see
 * `src/features/pwa/serviceWorker.ts`). Under `next dev` this file is served
 * exactly as written — an empty precache list — and nothing registers it.
 *
 * Updates take the browser's default path on purpose: a new worker installs
 * beside the old one and takes over once every tab of the app has closed.
 * Skipping the wait would swap the shell underneath a running page, which then
 * asks for chunks the new shell no longer has.
 */

// Rewritten by scripts/build-sw.mjs. Keep it on one line.
const BUILD = { version: 'dev', precache: [] }; // __SW_BUILD__

const PRECACHE = `gonoplan-precache-${BUILD.version}`;
const API_CACHE = 'gonoplan-api';
const TILE_CACHE = 'gonoplan-tiles';
const IMAGE_CACHE = 'gonoplan-images';
const KEEP = new Set([PRECACHE, API_CACHE, TILE_CACHE, IMAGE_CACHE]);

const OFFLINE_URL = '/offline/';
const API_PREFIX = '/api/v1';
const STAMP_HEADER = 'x-sw-cached-at';

const DAY_MS = 24 * 60 * 60 * 1000;

/** The basemap hosts in `src/lib/map/providers.ts`. */
const TILE_HOSTS = new Set(['tiles.goong.io', 'tiles.openfreemap.org']);

/*
 * The only API responses that are ever stored: public discovery reads.
 *
 * An allowlist, so a new endpoint is uncached until somebody decides
 * otherwise. Nothing under /auth, nothing an owner or admin sees, no saved
 * places or plans, and no write of any kind passes through this file.
 */
const CACHEABLE_API = [
  /^\/categories$/,
  /^\/recommendations(\/collections)?$/,
  /^\/places\/(nearby|map|search\/popular)$/,
  /^\/places\/[^/]+$/,
  /^\/places\/[^/]+\/reviews(\/summary)?$/,
];

// ─── Lifecycle ──────────────────────────────────────────────────────────────

self.addEventListener('install', (event) => {
  event.waitUntil(precache());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith('gonoplan-') && !KEEP.has(name))
          .map((name) => caches.delete(name)),
      );
      // So the very first visit is controlled without needing a reload.
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  // Sent on sign-out: a discovery response fetched while signed in can carry
  // that person's own flags, and must not outlive their session.
  if (event.data?.type === 'CLEAR_API_CACHE') {
    event.waitUntil(caches.delete(API_CACHE));
  }
});

/*
 * All or nothing. If one file fails the install fails, the browser retries on
 * a later visit, and the previous worker — with its complete shell — stays in
 * charge. Half a shell is worse than the old one.
 */
async function precache() {
  const cache = await caches.open(PRECACHE);
  const BATCH = 8;

  for (let i = 0; i < BUILD.precache.length; i += BATCH) {
    await Promise.all(
      BUILD.precache.slice(i, i + BATCH).map(async (url) => {
        // `reload` so the HTTP cache cannot hand back a file from the last build.
        const response = await fetch(url, { cache: 'reload' });
        if (!response.ok) throw new Error(`precache ${url}: ${String(response.status)}`);
        await cache.put(url, unredirected(response));
      }),
    );
  }
}

/**
 * A browser refuses to use a redirected response to answer a navigation, and
 * some static hosts redirect `/explore/` on the way to its index file.
 */
function unredirected(response) {
  if (!response.redirected) return response;
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

// ─── Routing ────────────────────────────────────────────────────────────────

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;

  // Matched by path, not origin: in development the API is proxied under this
  // origin, and a built client calls it on another one.
  if (url.pathname.startsWith(`${API_PREFIX}/`)) {
    const path = url.pathname.slice(API_PREFIX.length);
    if (CACHEABLE_API.some((pattern) => pattern.test(path))) {
      event.respondWith(networkFirst(event, API_CACHE, { timeoutMs: 3000, max: 80 }));
    }
    return;
  }

  if (url.origin === self.location.origin) {
    event.respondWith(shell(request, url));
    return;
  }

  if (TILE_HOSTS.has(url.hostname)) {
    event.respondWith(cacheFirst(event, TILE_CACHE, { max: 300, maxAgeMs: 7 * DAY_MS }));
    return;
  }

  if (request.destination === 'image') {
    // A small cap: a cross-origin photo is stored opaque, and browsers charge
    // an opaque entry against the quota at many times its real size.
    event.respondWith(cacheFirst(event, IMAGE_CACHE, { max: 60, maxAgeMs: 30 * DAY_MS }));
  }
});

/*
 * The app's own files: the precache, then the network.
 *
 * Looked up by path alone. Next adds a `?_rsc=` query to its payload requests
 * and every in-app link to a record is a query string (`/place?p=…`), and in a
 * static export none of that changes which file answers.
 */
async function shell(request, url) {
  const cache = await caches.open(PRECACHE);
  const isNavigation = request.mode === 'navigate';

  const hit = await cache.match(isNavigation ? asDirectory(url.pathname) : url.pathname);
  if (hit) return hit;

  try {
    return await fetch(request);
  } catch (error) {
    const offline = isNavigation ? await cache.match(OFFLINE_URL) : undefined;
    if (offline) return offline;
    throw error;
  }
}

/** `/explore` and `/explore/` are the same exported file. */
function asDirectory(pathname) {
  if (pathname.endsWith('/')) return pathname;
  const lastSegment = pathname.slice(pathname.lastIndexOf('/') + 1);
  return lastSegment.includes('.') ? pathname : `${pathname}/`;
}

// ─── Strategies ─────────────────────────────────────────────────────────────

/*
 * Fresh when the network answers, the last answer when it does not.
 *
 * The timeout is the part that matters on a phone: a connection that is
 * technically up but going nowhere would otherwise hold a screen empty for as
 * long as the request takes to give up.
 */
async function networkFirst(event, cacheName, { timeoutMs, max }) {
  const { request } = event;
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  const network = fetch(request).then((response) => {
    if (response.ok) event.waitUntil(store(cacheName, request, response.clone(), max));
    return response;
  });

  if (!cached) return network;

  // The race below may already have answered from the cache by the time this
  // settles; a rejection with nobody left listening is not an error.
  network.catch(() => undefined);

  const timeout = new Promise((resolve) => {
    setTimeout(resolve, timeoutMs);
  });

  try {
    const response = await Promise.race([network, timeout]);
    // No answer in time, or the server itself is failing: use what we have.
    if (!response || response.status >= 500) return cached;
    return response;
  } catch {
    return cached;
  }
}

/** For things that do not change under one URL: map tiles and photos. */
async function cacheFirst(event, cacheName, { max, maxAgeMs }) {
  const { request } = event;
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  if (cached && isFresh(cached, maxAgeMs)) return cached;

  try {
    const response = await fetch(request);
    if (response.ok || response.type === 'opaque') {
      event.waitUntil(store(cacheName, request, response.clone(), max));
    }
    return response;
  } catch (error) {
    // Out of date beats absent when there is no network to ask.
    if (cached) return cached;
    throw error;
  }
}

function isFresh(response, maxAgeMs) {
  const stamp = Number(response.headers.get(STAMP_HEADER));
  // An opaque response cannot be stamped; the entry cap is what bounds it.
  if (!stamp) return true;
  return Date.now() - stamp < maxAgeMs;
}

async function store(cacheName, request, response, max) {
  try {
    const cache = await caches.open(cacheName);
    await cache.put(request, stamped(response));

    // Oldest first — `keys()` returns entries in insertion order.
    const keys = await cache.keys();
    await Promise.all(keys.slice(0, Math.max(0, keys.length - max)).map((key) => cache.delete(key)));
  } catch {
    // Out of quota, or a response the Cache API will not take (`Vary: *`).
    // The page already has its answer; failing to keep a copy is not a failure.
  }
}

function stamped(response) {
  if (response.type === 'opaque') return response;

  const headers = new Headers(response.headers);
  headers.set(STAMP_HEADER, String(Date.now()));
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}
